"use strict";
/* ================= 頁 2:多日行程 ================= */
var LS_TRIPS="pocket_trips_v1";
var trips=[], curTrip=null, curDay=0;
try{trips=JSON.parse(localStorage.getItem(LS_TRIPS)||"[]");}catch(e){trips=[];}
function saveTrips(){try{localStorage.setItem(LS_TRIPS,JSON.stringify(trips));}catch(e){}}
function tripById(id){return trips.filter(function(t){return t.id===id;})[0];}
function curTripObj(){return curTrip?tripById(curTrip):null;}
function dayDateStr(t,i){
  if(!t.start)return "";
  var d=new Date(t.start+"T00:00:00");
  if(isNaN(d))return "";
  d.setDate(d.getDate()+i);
  return (d.getMonth()+1)+"/"+d.getDate();
}
function dayWeekStr(t,i){
  if(!t.start)return "";
  var d=new Date(t.start+"T00:00:00");
  if(isNaN(d))return "";
  d.setDate(d.getDate()+i);
  return "（"+"日一二三四五六".charAt(d.getDay())+"）";
}
function tripRangeStr(t){
  if(!t.start)return "未設定日期 · "+t.days.length+" 天";
  var s=new Date(t.start+"T00:00:00");
  if(isNaN(s))return t.days.length+" 天";
  var e=new Date(s); e.setDate(e.getDate()+t.days.length-1);
  var f=function(d){return d.getFullYear()+"/"+("0"+(d.getMonth()+1)).slice(-2)+"/"+("0"+d.getDate()).slice(-2);};
  return f(s)+" – "+f(e).slice(5)+" · "+t.days.length+" 天";
}
function showTripScreen(which){
  $("tripOverview").style.display=which==="overview"?"":"none";
  $("tripEditor").style.display=which==="editor"?"":"none";
  $("spotPicker").style.display=which==="picker"?"":"none";
  syncHeaderVisibility();
}
function renderTripList(){
  $("tripList").innerHTML=trips.length?trips.map(function(t){
    var n=t.days.reduce(function(a,d){return a+d.stops.length;},0);
    return '<div class="trip-card" data-id="'+attr(t.id)+'">'+
      '<div class="t">'+esc(t.name)+'</div>'+
      '<div class="d">'+esc(tripRangeStr(t))+(n?" · 共 "+n+" 個地點":" · 還沒排景點")+'</div></div>';
  }).join(""):'<p class="empty">還沒有行程,按下面建立一個。</p>';
  $("tripList").querySelectorAll(".trip-card").forEach(function(el){
    el.addEventListener("click",function(){openTrip(el.dataset.id);});
  });
}
function openTrip(id){
  curTrip=id; curDay=0;
  var t=curTripObj(); if(!t){curTrip=null;return;}
  mode=t.days[0].mode||"driving";
  loadDayIntoRoute();
  showTripScreen("editor");
  renderTripEditor();
}
function loadDayIntoRoute(){
  var t=curTripObj(); if(!t)return;
  var d=t.days[curDay]||{stops:[],mode:"driving"};
  route=d.stops.slice();
  mode=d.mode||"driving";
  legModes=d.legModes?Object.assign({},d.legModes):{};
  useCur=d.useCur!==false;
  addrOpen={};
  doneLeg={};
}
function syncDayFromRoute(){
  var t=curTripObj(); if(!t)return;
  if(!t.days[curDay])return;
  t.days[curDay].stops=route.slice();
  t.days[curDay].mode=mode;
  t.days[curDay].legModes=Object.assign({},legModes);
  t.days[curDay].useCur=useCur;
  saveTrips();
}
function renderTripEditor(){
  var t=curTripObj(); if(!t){showTripScreen("overview");renderTripList();return;}
  $("tripName").textContent=t.name;
  $("tripDates").textContent=tripRangeStr(t);
  $("dayTabs").innerHTML=t.days.map(function(d,i){
    return '<button type="button" class="day-tab'+(i===curDay?" on":"")+'" data-i="'+i+'" title="'+
      attr((dayDateStr(t,i)||"")+(d.stops.length?" · "+d.stops.length+" 站":""))+
      '"><span class="dt-date">'+esc(dayDateStr(t,i)||("D"+(i+1)))+'</span><span class="dt-day">第'+(i+1)+'天</span></button>';
  }).join("")+'<button type="button" class="day-tab add" id="dayAdd" title="加一天">＋</button>';
  $("dayTabs").querySelectorAll(".day-tab[data-i]").forEach(function(b){
    b.addEventListener("click",function(){
      syncDayFromRoute(); curDay=+b.dataset.i; loadDayIntoRoute(); renderTripEditor();
    });
  });
  $("dayAdd").addEventListener("click",function(){
    syncDayFromRoute();
    t.days.push({stops:[],mode:"driving",useCur:true});
    curDay=t.days.length-1; saveTrips(); loadDayIntoRoute(); renderTripEditor();
  });
  $("dayLabelTxt").textContent="Day "+(curDay+1)+" 停靠順序"+
    (dayDateStr(t,curDay)?" · "+dayDateStr(t,curDay)+dayWeekStr(t,curDay):"");
  $("routeOrder").style.display=dayListCollapsed?"none":"";
  $("dayLabelChev").textContent=dayListCollapsed?"▸":"▾";
  renderRoute();
}
$("btnTripBack").addEventListener("click",function(){
  syncDayFromRoute(); curTrip=null; showTripScreen("overview"); renderTripList();
});
$("btnNewTrip").addEventListener("click",function(){newTripFlow();});
$("btnTripEdit").addEventListener("click",function(){editTripFlow();});
var tfMode="new", tfDays=3;
function tfRangeText(){
  var start=$("tfStart").value;
  var txt=tfDays+" 天";
  if(start&&!isNaN(new Date(start+"T00:00:00"))){
    var s=new Date(start+"T00:00:00");
    var e=new Date(s); e.setDate(e.getDate()+tfDays-1);
    var f=function(d){return d.getFullYear()+"/"+("0"+(d.getMonth()+1)).slice(-2)+"/"+("0"+d.getDate()).slice(-2);};
    txt=f(s)+" – "+f(e).slice(5)+" · "+tfDays+" 天";
  }
  return txt;
}
function updateTfUI(){
  $("tfDaysVal").textContent=tfDays;
  $("tfRange").textContent=tfRangeText();
}
function openTripForm(mode){
  tfMode=mode;
  var t=mode==="edit"?curTripObj():null;
  if(mode==="edit"&&!t)return;
  $("tripFormTitle").textContent=mode==="edit"?"編輯行程":"建立新行程";
  $("tfName").value=mode==="edit"?t.name:"關西之旅";
  tfDays=mode==="edit"?t.days.length:3;
  $("tfStart").value=mode==="edit"?(t.start||""):"";
  $("tfDelete").style.display=mode==="edit"?"":"none";
  updateTfUI();
  $("tripFormBk").classList.add("show");$("tripFormSheet").classList.add("show");
  setTimeout(function(){$("tfName").focus();},260);
}
function closeTripForm(){
  $("tripFormBk").classList.remove("show");$("tripFormSheet").classList.remove("show");
}
$("tfDaysMinus").addEventListener("click",function(){tfDays=Math.max(1,tfDays-1);updateTfUI();});
$("tfDaysPlus").addEventListener("click",function(){tfDays=Math.min(30,tfDays+1);updateTfUI();});
$("tfStart").addEventListener("change",updateTfUI);
$("tripFormBk").addEventListener("click",closeTripForm);
$("tfSave").addEventListener("click",function(){
  var name=$("tfName").value.trim()||"未命名行程";
  var start=$("tfStart").value||"";
  if(start&&isNaN(new Date(start+"T00:00:00")))start="";
  if(tfMode==="new"){
    var t={id:uid(),name:name,start:start||null,days:[]};
    for(var i=0;i<tfDays;i++)t.days.push({stops:[],mode:"driving",useCur:true});
    trips.push(t); saveTrips(); closeTripForm(); renderTripList(); openTrip(t.id);
  }else{
    var t=curTripObj(); if(!t){closeTripForm();return;}
    if(tfDays<t.days.length){
      var removed=t.days.slice(tfDays);
      var hasStops=removed.some(function(d){return d.stops&&d.stops.length;});
      if(hasStops&&!confirm("縮減天數會刪除後面天數已排的景點,確定嗎?")){return;}
      t.days=t.days.slice(0,tfDays);
      if(curDay>=t.days.length)curDay=t.days.length-1;
    }else if(tfDays>t.days.length){
      while(t.days.length<tfDays)t.days.push({stops:[],mode:"driving",useCur:true});
    }
    t.name=name; t.start=start||null;
    saveTrips(); closeTripForm(); loadDayIntoRoute(); renderTripEditor();
  }
});
$("tfDelete").addEventListener("click",function(){
  var t=curTripObj(); if(!t)return;
  if(!confirm("要刪除「"+t.name+"」這個行程嗎?此動作無法復原。"))return;
  trips=trips.filter(function(x){return x.id!==t.id;});
  saveTrips(); curTrip=null; closeTripForm(); showTripScreen("overview"); renderTripList();
});
function newTripFlow(){openTripForm("new");}
function editTripFlow(){openTripForm("edit");}
$("btnAddSpots").addEventListener("click",function(){
  syncDayFromRoute();
  $("pickTitle").textContent="加到 Day "+(curDay+1);
  showTripScreen("picker"); renderRoutePick();
});
$("btnPickBack").addEventListener("click",function(){
  showTripScreen("editor"); renderTripEditor();
});
var route=[], mode="driving", legModes={}, doneLeg={}, useCur=true, rCat="全部", rqText="";
var LEG_MODE_ORDER=["driving","walking","transit"];
var LEG_MODE_LABEL={driving:"開車",walking:"走路",transit:"大眾運輸"};
var LEG_MODE_ICON={driving:"🚗",walking:"🚶",transit:"🚋"};
function legMode(i){return legModes[i]||mode;}
function renderRouteFilters(){
  var rl=$("rList"),cur=rl.value||"__all__";
  var h='<option value="__all__">全部清單</option>';
  lists.forEach(function(l){h+='<option value="'+attr(l)+'"'+(l===cur?" selected":"")+'>'+esc(l)+'</option>';});
  rl.innerHTML=h;
  var base=places.filter(function(p){var l=rl.value||"__all__";return l==="__all__"||p.list===l;});
  var seen=["全部"];
  base.forEach(function(x){if(seen.indexOf(x.cat)<0)seen.push(x.cat);});
  if(seen.indexOf(rCat)<0)rCat="全部";
  $("rCats").innerHTML=seen.map(function(c){
    var n=c==="全部"?base.length:base.filter(function(x){return x.cat===c;}).length;
    return '<button class="chip'+(c===rCat?" on":"")+'" data-c="'+attr(c)+'">'+esc(c)+' '+n+'</button>';
  }).join("");
  $("rCats").querySelectorAll(".chip").forEach(function(b){
    b.addEventListener("click",function(){rCat=b.dataset.c;renderRoutePick();});
  });
}
function renderRoutePick(){
  renderRouteFilters();
  var l=$("rList").value||"__all__";
  var t=curTripObj();
  var avail=places.filter(function(p){
    if(l!=="__all__"&&p.list!==l)return false;
    if(rCat!=="全部"&&p.cat!==rCat)return false;
    if(rqText&&p.name.indexOf(rqText)<0)return false;
    return true;
  });
  function dayOf(pid){
    if(!t)return -1;
    for(var i=0;i<t.days.length;i++){
      if(i===curDay)continue;
      if(t.days[i].stops.some(function(s){return s.pid===pid;}))return i;
    }
    return -1;
  }
  $("routePick").innerHTML=avail.length?avail.map(function(x){
    var i=route.findIndex(function(s){return s.pid===x.id;});
    var od=dayOf(x.id);
    return '<div class="pickrow'+(i>=0?" on":"")+'" data-pid="'+attr(x.id)+'">'+
    '<span class="box">'+(i>=0?(i+1):"")+'</span>'+
    '<span class="n">'+esc(x.name)+'</span><span class="c">'+esc(x.cat)+'</span>'+
    (od>=0?'<span class="pick-day">Day '+(od+1)+'</span>':'')+'</div>';
  }).join(""):'<p class="empty">'+(places.length?"這個條件下沒有景點,換個分類或清單試試。":"口袋名單還是空的,先到「口袋名單」新增或用右上角「匯入」搬家。")+'</p>';
  $("routePick").querySelectorAll(".pickrow").forEach(function(r){
    r.addEventListener("click",function(){
      var pid=r.dataset.pid,i=route.findIndex(function(s){return s.pid===pid;});
      if(i>=0)route.splice(i,1);
      else{var p=places.find(function(x){return x.id===pid;});route.push({name:p.name,pid:pid,tmp:false});}
      doneLeg={};syncDayFromRoute();renderRoutePick();
    });
  });
}
var expandedStop=null, dayListCollapsed=false, addrOpen={};
function stopAddr(s){
  if(!s)return "";
  if(s.addr)return s.addr;   /* 臨時點:自動完成選到的地點會直接帶地址 */
  if(!s.pid)return "";
  var p=places.filter(function(x){return x.id===s.pid;})[0];
  return (p&&p.addr)?p.addr:"";
}
function stopPlace(s){
  if(!s)return null;
  if(s.pid)return places.filter(function(x){return x.id===s.pid;})[0]||null;
  /* 臨時點:用名稱去比對口袋名單,對到就能沿用它的照片與分類 */
  if(s.name){
    var m=places.filter(function(x){return x.name===s.name;})[0];
    if(m)return m;
  }
  return null;
}
/* 停靠點縮圖:有照片就顯示照片,沒有才退回依名稱產生的漸層色塊 */
function stopThumb(s,p){
  var key=s.pid||s.name;
  var url=(s&&s.photoUrl)?s.photoUrl:((p&&p.photoUrl)?p.photoUrl:null);
  if(url){
    return '<div class="stop2-thumb"><img src="'+attr(url)+'" alt="" loading="lazy" '+
           'onerror="phThumbErr(this,\''+attr(key)+'\')"></div>';
  }
  return '<div class="stop2-thumb" style="background:'+placeGradient(key)+';"></div>';
}
/* 臨時地點(不在口袋名單裡)也去抓一次 Google 的照片與簡介,存在該停靠點自己身上 */
function fetchStopPhoto(idx,name){
  if(!gKey()||typeof googlePlacePhoto!=="function")return;
  googlePlacePhoto(name,"",function(res){
    var s=route[idx];
    if(!s||!res)return;
    if(res.photoUrl)s.photoUrl=res.photoUrl;
    if(res.autoDesc)s.autoDesc=res.autoDesc;
    if(res.photoUrl||res.autoDesc){syncDayFromRoute();renderRoute();}
  },function(){});
}
function toggleStopExpand(i){
  expandedStop=(expandedStop===i)?null:i;
  renderRoute();
}
var esIdx=null, esPlace=null, esAutoDone=false, esLastAC="";
function editStop(i){
  var s=route[i]; if(!s)return;
  esIdx=i; esPlace=null;
  $("esInput").value=s.name||"";
  $("esBk").classList.add("show");
  $("esSheet").classList.add("show");
  ensureGoogleMapsLoaded();
  esInitAutocomplete();
  setTimeout(function(){$("esInput").focus();$("esInput").select();},250);
}
function esInitAutocomplete(){
  if(esAutoDone||!window.google||!google.maps||!google.maps.places)return;
  esAutoDone=true;
  var opts={fields:["place_id","formatted_address","name","geometry"]};
  var ac=new google.maps.places.Autocomplete($("esInput"),opts);
  ac.addListener("place_changed",function(){
    esPlace=ac.getPlace();
    gTrackDetail("autocomplete");
    /* Google 選完會把整串地址塞回輸入框,改回店名比較好讀,也避免地址被當成名稱存下去 */
    if(esPlace&&esPlace.name){esLastAC=esPlace.name;$("esInput").value=esPlace.name;}
    else{esLastAC=$("esInput").value;}
  });
  $("esInput").addEventListener("input",function(){
    /* 只有「真的是使用者在改字」才清掉已選地點;Google 自己填值不算 */
    if(this.value!==esLastAC)esPlace=null;
  });
  $("esInput").addEventListener("keydown",function(e){
    if(e.key==="Enter"&&!e.isComposing){e.preventDefault();}
  });
}
function closeEditStop(){
  $("esBk").classList.remove("show");
  $("esSheet").classList.remove("show");
  esIdx=null;esPlace=null;
}
function saveEditStop(){
  if(esIdx===null)return;
  var val=$("esInput").value.trim();
  if(!val){toast("請輸入地點名稱");return;}
  var oldTime=(route[esIdx]&&route[esIdx].time)||"";
  var item={name:val,pid:null,tmp:true,time:oldTime};
  if(esPlace&&esPlace.geometry&&esPlace.geometry.location){
    item.lat=esPlace.geometry.location.lat();
    item.lng=esPlace.geometry.location.lng();
    if(esPlace.name)item.name=esPlace.name;
    if(esPlace.formatted_address)item.addr=esPlace.formatted_address;
  }
  route[esIdx]=item;
  var idx=esIdx;
  closeEditStop();
  expandedStop=null;
  doneLeg={};syncDayFromRoute();renderTripEditor();
  if(!stopPlace(item))fetchStopPhoto(idx,item.name);
}
function renderRoute(){
  if(expandedStop!=null&&expandedStop>=route.length)expandedStop=null;
  $("routeOrder").innerHTML=
  '<div class="stop start" id="startRow">'+
  '<span class="num">'+(useCur?"起":"—")+'</span>'+
  '<span class="n" style="color:var(--text2);font-weight:400;">'+(useCur?"目前位置":"不用目前位置,直接從第 1 站出發")+'</span>'+
  '<span style="font-size:11.5px;color:var(--accent);white-space:nowrap;">點一下切換</span></div>'+
  (route.length?route.map(function(s,i){
    var exp=expandedStop===i;
    var addr=stopAddr(s);
    var p=stopPlace(s);
    var desc=(p&&p.autoDesc)||s.autoDesc||"";
    var upBtn=i>0?'<button class="stop2-ic" data-mv="'+i+',-1" aria-label="上移">↑</button>':'<span class="stop2-ic off">↑</span>';
    var downBtn=i<route.length-1?'<button class="stop2-ic" data-mv="'+i+',1" aria-label="下移">↓</button>':'<span class="stop2-ic off">↓</span>';
    var meta='';
    if(exp){
      if(desc)meta+='<div class="stop2-desc">'+esc(desc)+'</div>';
      if(p&&p.note)meta+='<div class="stop2-note">📝 '+esc(p.note)+'</div>';
      if(addr){
        var aOpen=!!addrOpen[i];
        meta+='<button type="button" class="addr-toggle" data-atg="'+i+'">地址 '+(aOpen?'▴':'▾')+'</button>';
        if(aOpen)meta+='<div class="stop2-addr">'+esc(addr)+'</div>';
      }
    }
    var thumbHtml=stopThumb(s,p);
    var hasNext=i<route.length-1;
    var timeVal=s.time||"";
    var card='<div class="stop2" data-i="'+i+'">'+
      '<div class="stop2-line"><input type="time" class="stop2-time'+(timeVal?" set":"")+'" data-ti="'+i+'" value="'+attr(timeVal)+'" aria-label="時間">'+
      (hasNext?'<span class="bar"></span>':'')+'</div>'+
      '<div class="stop2-right">'+
      '<div class="stop2-card'+(exp?" exp":"")+'">'+
        '<div class="stop2-main">'+
          '<div style="flex:1;min-width:0;">'+
            '<div class="stop2-name">'+esc(s.name)+'</div>'+
            (meta?'<div class="stop2-meta">'+meta+'</div>':'')+
            (exp?'<div class="stop2-arrows2">'+upBtn+downBtn+'</div>':'')+
          '</div>'+
          (!exp?thumbHtml:'')+
          (!exp?upBtn+downBtn+'<button class="stop2-ic stop2-more" data-more="'+i+'" aria-label="更多">⋯</button>'
              :'<button class="stop2-ic stop2-more on" data-more="'+i+'" aria-label="收合">⋯</button>')+
        '</div>'+
        (exp?'<div class="stop2-actions">'+
          '<button data-edit="'+i+'" aria-label="編輯">'+IC.edit+'</button>'+
          '<button class="del" data-rm="'+i+'" aria-label="刪除">'+IC.x+'</button>'+
        '</div>':'')+
      '</div>';
    if(hasNext){
      var lm=legMode(i);
      card+='<button type="button" class="legrow" data-leg2="'+i+'" title="點一下切換這段的交通方式">'+
        '<span class="ic">'+LEG_MODE_ICON[lm]+'</span><span>'+LEG_MODE_LABEL[lm]+'</span>'+
        '<span class="tm" id="legt-'+i+'">· …</span><span class="chev">▾</span></button>';
    }
    card+='</div></div>';
    return card;
  }).join(""):'<p class="empty">還沒有停靠點,在上方點選或插入臨時地點。</p>');
  $("routeOrder").querySelectorAll("[data-mv]").forEach(function(b){
    b.addEventListener("click",function(){
      var a=b.dataset.mv.split(","),i=+a[0],d=+a[1],t=route[i];
      route[i]=route[i+d];route[i+d]=t;doneLeg={};expandedStop=null;syncDayFromRoute();renderTripEditor();
    });
  });
  $("routeOrder").querySelectorAll("[data-ti]").forEach(function(inp){
    inp.addEventListener("change",function(){
      var i=+inp.dataset.ti;
      if(!route[i])return;
      route[i].time=inp.value||"";
      inp.classList.toggle("set",!!inp.value);
      syncDayFromRoute();
    });
  });
  $("routeOrder").querySelectorAll("[data-atg]").forEach(function(b){
    b.addEventListener("click",function(){
      var i=+b.dataset.atg;
      addrOpen[i]=!addrOpen[i];
      renderRoute();
    });
  });
  $("routeOrder").querySelectorAll("[data-rm]").forEach(function(b){
    b.addEventListener("click",function(){route.splice(+b.dataset.rm,1);expandedStop=null;doneLeg={};syncDayFromRoute();renderTripEditor();});
  });
  $("routeOrder").querySelectorAll("[data-more]").forEach(function(b){
    b.addEventListener("click",function(){toggleStopExpand(+b.dataset.more);});
  });
  $("routeOrder").querySelectorAll("[data-edit]").forEach(function(b){
    b.addEventListener("click",function(){editStop(+b.dataset.edit);});
  });
  $("routeOrder").querySelectorAll("[data-leg2]").forEach(function(b){
    b.addEventListener("click",function(){
      var i=+b.dataset.leg2, cur=legMode(i), idx=LEG_MODE_ORDER.indexOf(cur);
      legModes[i]=LEG_MODE_ORDER[(idx+1)%LEG_MODE_ORDER.length];
      doneLeg={};syncDayFromRoute();renderRoute();
    });
  });
  $("startRow").addEventListener("click",function(){useCur=!useCur;doneLeg={};syncDayFromRoute();renderRoute();});
  var anyTransit=route.some(function(s,i){return i<route.length-1&&legMode(i)==="transit";});
  var mixed=(function(){
    if(route.length<2)return false;
    var first=legMode(0);
    for(var i=1;i<route.length-1;i++)if(legMode(i)!==first)return true;
    return false;
  })();
  $("transitNote").style.display=(anyTransit||mixed)&&route.length>1?"block":"none";
  $("maxNote").style.display=(!anyTransit&&!mixed&&route.length>9)?"block":"none";
  renderGo();
  ensureLegTimes();
  if(typeof renderRouteMap==="function")renderRouteMap();
}
if($("dayLabel"))$("dayLabel").addEventListener("click",function(){
  dayListCollapsed=!dayListCollapsed;
  $("routeOrder").style.display=dayListCollapsed?"none":"";
  $("dayLabelChev").textContent=dayListCollapsed?"▸":"▾";
});

/* ================= 停靠點間交通時間(行內顯示,支援每段各自的交通方式) ================= */
var rsCache={};
function legKey(){
  if(!curTrip||route.length<2)return null;
  var modesStr=route.slice(0,-1).map(function(s,i){return legMode(i);}).join(",");
  return curTrip+"|"+curDay+"|"+modesStr+"|"+route.map(function(s){return s.name;}).join(">");
}
function applyLegTimes(){
  var key=legKey(); var c=key&&rsCache[key];
  if(!c||!c.legs)return;
  c.legs.forEach(function(t,i){var el=$("legt-"+i); if(el)el.textContent="· "+(t||"…");});
}
function ensureLegTimes(){
  var key=legKey();
  if(!key)return;
  if(!gmapsLoaded){ensureGoogleMapsLoaded();return;}
  var c=rsCache[key];
  if(c&&c.legs){applyLegTimes();return;}
  if(c&&c.loading)return;
  rsCache[key]={loading:true};
  var n=route.length-1;
  var legs=new Array(n);
  var modeGroups={};
  for(var i=0;i<n;i++){var lm=legMode(i);(modeGroups[lm]=modeGroups[lm]||[]).push(i);}
  var modeKeys=Object.keys(modeGroups);
  if(!modeKeys.length){rsCache[key]={loading:false,legs:legs};applyLegTimes();return;}
  var remaining=modeKeys.length;
  modeKeys.forEach(function(lm){
    var idxs=modeGroups[lm];
    var origins=idxs.map(function(i){return route[i].name;});
    var destinations=idxs.map(function(i){return route[i+1].name;});
    var tmode=lm==="walking"?google.maps.TravelMode.WALKING:
      lm==="transit"?google.maps.TravelMode.TRANSIT:google.maps.TravelMode.DRIVING;
    var svc=new google.maps.DistanceMatrixService();
    gTrackDetail("distancematrix");
    svc.getDistanceMatrix({origins:origins,destinations:destinations,travelMode:tmode},function(res,status){
      idxs.forEach(function(i,j){
        var el=(status==="OK"&&res&&res.rows[j]&&res.rows[j].elements[j]);
        legs[i]=el&&el.status==="OK"?el.duration.text:"—";
        if(!(el&&el.status==="OK"))console.warn("[路線時間] 第"+(i+1)+"段("+lm+")取得失敗",status,el&&el.status);
      });
      remaining--;
      if(remaining===0){
        rsCache[key]={loading:false,legs:legs};
        if(legKey()===key)applyLegTimes();
      }
    });
  });
}

/* ================= 停靠順序小地圖 ================= */
var rMap=null, rMapMarkers=[], rMapPoly=null, rMapDirRenderer=null, rMapOpen=false, rMapKey=null;
$("rMapToggle").addEventListener("click",function(){
  rMapOpen=!rMapOpen;
  $("rMapBox").style.display=rMapOpen?"block":"none";
  $("rMapToggle").textContent=rMapOpen?"🗺️ 收合地圖":"🗺️ 顯示路線地圖";
  if(rMapOpen)renderRouteMap();
});
function rMapSig(){
  var pts=useCur?[{cur:true}]:[];
  pts=pts.concat(route);
  return (curTrip?curTrip.id:"")+"|"+curDay+"|"+mode+"|"+pts.map(function(p){return p.cur?"@cur":p.name;}).join(">");
}
function rMapClearOverlays(){
  rMapMarkers.forEach(function(m){m.setMap(null);});rMapMarkers=[];
  if(rMapPoly){rMapPoly.setMap(null);rMapPoly=null;}
  if(rMapDirRenderer){rMapDirRenderer.setMap(null);rMapDirRenderer=null;}
}
function renderRouteMap(){
  if(!rMapOpen)return;
  if(!gmapsLoaded){
    ensureGoogleMapsLoaded();
    $("rMapBox").innerHTML='<p class="empty" style="margin:0;padding:80px 10px 0;">地圖載入中,請確認已在「資料來源設定」貼上 Google API 金鑰…</p>';
    setTimeout(function(){if(rMapOpen&&gmapsLoaded)renderRouteMap();},1200);
    return;
  }
  var pts=(useCur?[{cur:true}]:[]).concat(route);
  if(!pts.length){$("rMapBox").innerHTML='<p class="empty" style="margin:0;padding:80px 10px 0;">還沒有停靠點</p>';return;}
  var sig=rMapSig();
  if(rMapKey===sig&&rMap)return;
  rMapKey=sig;
  $("rMapBox").innerHTML='<div id="rMapCanvas" style="width:100%;height:100%;"></div>';
  Promise.all(pts.map(function(p){
    if(p.cur&&myPos)return Promise.resolve({lat:myPos.lat,lng:myPos.lng});
    var c=coordOf(p);
    if(c&&c.lat!=null&&c.lng!=null)return Promise.resolve(c);
    return ppGeocode(p.name);
  })).then(function(coords){
    if(rMapKey!==sig)return;
    var valid=[];
    coords.forEach(function(c,i){if(c&&c.lat!=null&&c.lng!=null)valid.push({c:c,p:pts[i],i:i});});
    var canvas=$("rMapCanvas");
    if(!canvas)return;
    if(!valid.length){$("rMapBox").innerHTML='<p class="empty" style="margin:0;padding:70px 10px 0;">找不到座標,請確認站名拼字,或到「資料來源設定」貼上 Google API 金鑰。</p>';return;}
    rMap=new google.maps.Map(canvas,{center:{lat:valid[0].c.lat,lng:valid[0].c.lng},zoom:12,disableDefaultUI:true,zoomControl:true,gestureHandling:"greedy"});
    gTrackDetail("mapsjs");
    rMapClearOverlays();
    var bounds=new google.maps.LatLngBounds();
    valid.forEach(function(v){
      var isCur=!!v.p.cur;
      var marker=new google.maps.Marker({
        position:{lat:v.c.lat,lng:v.c.lng},map:rMap,
        label:{text:isCur?"起":String(v.i+(pts[0].cur?0:1)),color:"#ffffff",fontSize:"12px",fontWeight:"800"},
        icon:{path:google.maps.SymbolPath.CIRCLE,scale:13,fillColor:isCur?"#8fa0b8":"#F0B84A",fillOpacity:1,strokeColor:"#ffffff",strokeWeight:2}
      });
      rMapMarkers.push(marker);
      bounds.extend(marker.getPosition());
    });
    rMap.fitBounds(bounds,40);
    if(valid.length>1)drawRouteMapPath(valid,sig);
  });
}
function drawRouteMapPath(valid,sig){
  var latlngs=valid.map(function(v){return {lat:v.c.lat,lng:v.c.lng};});
  function fallbackDashedLine(){
    if(rMapKey!==sig||!rMap)return;
    rMapPoly=new google.maps.Polyline({path:latlngs,geodesic:true,strokeOpacity:0,map:rMap,
      icons:[{icon:{path:"M 0,-1 0,1",strokeOpacity:1,scale:3,strokeColor:"#F0B84A"},offset:"0",repeat:"12px"}]});
  }
  if(mode==="transit"||latlngs.length>10){fallbackDashedLine();return;}
  var svc=new google.maps.DirectionsService();
  gTrackDetail("directions");
  var tmode=mode==="walking"?google.maps.TravelMode.WALKING:google.maps.TravelMode.DRIVING;
  var origin=latlngs[0],dest=latlngs[latlngs.length-1],wp=latlngs.slice(1,-1).map(function(l){return{location:l,stopover:true};});
  svc.route({origin:origin,destination:dest,waypoints:wp,travelMode:tmode,optimizeWaypoints:false},function(res,status){
    if(rMapKey!==sig||!rMap)return;
    if(status==="OK"){
      rMapDirRenderer=new google.maps.DirectionsRenderer({map:rMap,directions:res,suppressMarkers:true,preserveViewport:true,
        polylineOptions:{strokeColor:"#F0B84A",strokeWeight:5,strokeOpacity:.9}});
    }else{
      console.warn("[路線地圖] 路徑計算失敗",status);
      fallbackDashedLine();
    }
  });
}
function legEffModeAt(k){
  if(useCur)return k===0?legMode(0):legMode(k-1);
  return legMode(k);
}
function renderGo(){
  if(!route.length){$("goArea").innerHTML='<button class="btn-primary" disabled>先點選或插入地點</button>';return;}
  if(!useCur&&route.length===1){
    $("goArea").innerHTML='<button class="btn-primary" id="goAll">開啟 Google 地圖(只有 1 個地點)</button>';
    $("goAll").addEventListener("click",function(){gmapSearch(route[0].name);});
    return;
  }
  var legTotal=useCur?route.length:route.length-1;
  var modesArr=[]; for(var k=0;k<legTotal;k++)modesArr.push(legEffModeAt(k));
  var uniform=modesArr.every(function(m){return m===modesArr[0];});
  var uniMode=modesArr[0]||"driving";
  if(uniform&&(uniMode!=="transit"||legTotal<=1)){
    $("goArea").innerHTML='<button class="btn-primary" id="goAll">開啟 Google 導航 · '+route.length+' 站</button>';
    $("goAll").addEventListener("click",function(){
      var names=route.map(function(s){return s.name;}).slice(0,10);
      var u="https://www.google.com/maps/dir/?api=1&travelmode="+uniMode;
      if(useCur){
        var dest=names[names.length-1],wp=names.slice(0,-1);
        u+="&destination="+encodeURIComponent(dest)+(wp.length?"&waypoints="+encodeURIComponent(wp.join("|")):"");
      }else{
        var org=names[0],dest2=names[names.length-1],wp2=names.slice(1,-1);
        u+="&origin="+encodeURIComponent(org)+"&destination="+encodeURIComponent(dest2)+
          (wp2.length?"&waypoints="+encodeURIComponent(wp2.join("|")):"");
      }
      window.open(u,"_blank");
    });
    return;
  }
  var h='<div class="section-label" style="margin-top:0;">分段導航・共 '+legTotal+' 段</div>';
  for(var k2=0;k2<legTotal;k2++){
    var fi=useCur?k2-1:k2, ti=useCur?k2:k2+1;
    var from=fi<0?"目前位置":route[fi].name, to=route[ti].name, ok=doneLeg[k2];
    var lm2=modesArr[k2];
    h+='<button class="leg'+(ok?" ok2":"")+'" data-leg="'+k2+'">'+
    '<span class="num">'+(ok?"✓":(k2+1))+'</span>'+
    '<span class="t">'+LEG_MODE_ICON[lm2]+' '+esc(from)+' → '+esc(to)+'</span><span style="display:inline-flex;color:var(--accent);">'+IC.ext+'</span></button>';
  }
  $("goArea").innerHTML=h;
  $("goArea").querySelectorAll("[data-leg]").forEach(function(b){
    b.addEventListener("click",function(){
      var k=+b.dataset.leg, fi=useCur?k-1:k, ti=useCur?k:k+1, lm=legEffModeAt(k);
      var u="https://www.google.com/maps/dir/?api=1&destination="+encodeURIComponent(route[ti].name)+"&travelmode="+lm;
      if(fi>=0)u+="&origin="+encodeURIComponent(route[fi].name);
      doneLeg[k]=true;renderGo();window.open(u,"_blank");
    });
  });
}
$("rq").addEventListener("input",function(){rqText=this.value.trim();renderRoutePick();});
$("rList").addEventListener("change",function(){rCat="全部";renderRoutePick();});
$("btnTmp").addEventListener("click",function(){
  var n=$("tmpName").value.trim();
  if(!n){$("tmpName").focus();return;}
  var stop={name:n,pid:null,tmp:true,time:""};
  if(tmpPlace&&tmpPlace.geometry&&tmpPlace.geometry.location){
    stop.lat=tmpPlace.geometry.location.lat();
    stop.lng=tmpPlace.geometry.location.lng();
    if(tmpPlace.formatted_address)stop.addr=tmpPlace.formatted_address;
  }
  route.push(stop);
  var newIdx=route.length-1;
  $("tmpName").value="";tmpPlace=null;doneLeg={};syncDayFromRoute();renderTripEditor();
  if(!stopPlace(stop))fetchStopPhoto(newIdx,n);
});
$("btnTmpSave").addEventListener("click",function(){
  var n=$("tmpName").value.trim();
  if(!n){$("tmpName").focus();return;}
  if(hasPlace(n)){toast("「"+n+"」已經在口袋名單裡了");return;}
  var item={id:uid(),name:n,cat:guessCat(n),list:lists[0]||"未分類",note:"",done:false};
  if(tmpPlace&&tmpPlace.geometry&&tmpPlace.geometry.location){
    item.lat=tmpPlace.geometry.location.lat();
    item.lng=tmpPlace.geometry.location.lng();
  }
  places.unshift(item);
  save();
  toast("已加入口袋名單「"+n+"」");
  tmpPlace=null;
  queuePlacePhotos(); /* 新加的項目在陣列最前面,會被優先抓照片跟簡述 */
});
var tmpPlace=null, tmpAutoDone=false, tmpLastAC="";
function tmpInitAutocomplete(){
  if(tmpAutoDone||!window.google||!google.maps||!google.maps.places)return;
  tmpAutoDone=true;
  var opts={componentRestrictions:{country:"jp"},fields:["place_id","formatted_address","name","geometry"]};
  var ac=new google.maps.places.Autocomplete($("tmpName"),opts);
  ac.addListener("place_changed",function(){
    tmpPlace=ac.getPlace();
    gTrackDetail("autocomplete");
    /* Google 選完會把整串地址塞回輸入框,改回店名比較好讀,也避免地址被當成名稱存下去 */
    if(tmpPlace&&tmpPlace.name){tmpLastAC=tmpPlace.name;$("tmpName").value=tmpPlace.name;}
    else{tmpLastAC=$("tmpName").value;}
  });
  $("tmpName").addEventListener("input",function(){
    if(this.value!==tmpLastAC)tmpPlace=null;
  });
}
$("tmpName").addEventListener("focus",function(){ensureGoogleMapsLoaded();});

